using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: the default discriminator property was
        // renamed from "Discriminator" to "$type".  Existing documents already
        // store "Discriminator", so we must opt back into the old name.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// EF Core 9 breaking change: synchronous Cosmos DB I/O now throws by default.
// All queries must use the async pipeline.
class ProductService
{
    // BEFORE (EF Core 8 – worked but is now blocked):
    //   var list = db.Products.ToList();
    //
    // AFTER (EF Core 9 – use async):
    async Task<List<Product>> GetAllAsync(CosmosDbContext db)
        => await db.Products.ToListAsync();

    async Task<Product?> FindAsync(CosmosDbContext db, string id)
        => await db.Products.FirstOrDefaultAsync(p => p.Id == id);
}

